 | \\u2705 | \\u2705 |\\n| eastus2 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| francecentral | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| germanywestcentral | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| italynorth | \\u2705 | \\u2705 | \\u2705 | \\u2705 | - | - | - | - | - | - | - |\\n| northcentralus | \\u2705 | \\u2705 | \\u2705 | - | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| polandcentral | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| southcentralus | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| spaincentral | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| swedencentral | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| westeurope | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| westus | \\u2705 | \\u2705 | \\u2705 | - | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n| westus3 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 | \\u2705 |\\n\\n**Data Zone Batch**\\n### Data zone batch model availability\", \"contentUrl\": \"https://learn.microsoft.com/azure/ai-foundry/openai/concepts/models#model-summary-table-and-region-availability\"}]}","server_label":"microsoft-learn"},{"id":"rs_0447f380642eed83006aa1180ff2c487d08037d9592b8848d0","type":"reasoning","content":[],"encrypted_content":"","summary":[]},{"id":"mcp_0447f380642eed83006aa11810a2f487d0a1f088c5f152b9d9","type":"mcp_call","status":"completed","approval_request_id":null,"arguments":"{\"query\":\"Azure OpenAI differences between OpenAI and Azure OpenAI switching endpoints deployment name vs model name how-to switching endpoints\"}","error":null,"name":"microsoft_docs_search","output":"{\"results\": [{\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints with Python\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints with Python\\n## Keyword argument for model\\nOpenAI uses the `model` keyword argument to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/azure/foundry-classic/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nWhen you access the model via the API in Azure OpenAI, you need to refer to the deployment name rather than the underlying model name in API calls, which is one of the [key differences](https://learn.microsoft.com/azure/foundry-classic/openai/how-to/switching-endpoints) between OpenAI and Azure OpenAI. OpenAI only requires the model name. Azure OpenAI always requires deployment name, even when using the model parameter. In our docs, we often have examples where deployment names are represented as identical to model names to help indicate which model works with a particular API endpoint. Ultimately your deployment names can follow whatever naming convention is best for your use case.\\n| OpenAI | Azure OpenAI| \\n|  --- | ---  |\\n| ```python<br>response = client.responses.create(   <br>    model=\\\"gpt-4.1-nano\\\", # Replace with your model deployment name <br>    input=\\\"This is a test.\\\"<br>)<br><br>chat_completion = client.chat.completions.create(<br>    model=\\\"gpt-4o\\\",<br>    messages=\\\"<messages>\\\"<br>)<br><br>embedding = client.embeddings.create(<br>    model=\\\"text-embedding-3-large\\\",<br>    input=\\\"<input>\\\"<br>)<br>``` | ```python<br>response = client.responses.create(   <br>    model=\\\"gpt-4.1-nano\\\", # Replace with your model deployment name <br>    input=\\\"This is a test.\\\"<br>)<br><br>chat_completion = client.chat.completions.create(<br>    model=\\\"gpt-4o\\\", # model = \\\"deployment_name\\\".<br>    messages=\\\"<messages>\\\"<br>)<br><br>embedding = client.embeddings.create(<br>    model=\\\"text-embedding-3-large\\\", # model = \\\"deployment_name\\\".<br>    input=\\\"<input>\\\"<br>)<br>``` |\\n\", \"contentUrl\": \"https://learn.microsoft.com/azure/foundry-classic/openai/how-to/switching-endpoints#keyword-argument-for-model\"}, {\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints with Python\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints with Python\\n## Keyword argument for model\\nOpenAI uses the `model` keyword argument to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nWhen you access the model via the API in Azure OpenAI, you need to refer to the deployment name rather than the underlying model name in API calls, which is one of the [key differences](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/switching-endpoints) between OpenAI and Azure OpenAI. OpenAI only requires the model name. Azure OpenAI always requires deployment name, even when using the model parameter. In our docs, we often have examples where deployment names are represented as identical to model names to help indicate which model works with a particular API endpoint. Ultimately your deployment names can follow whatever naming convention is best for your use case.\\n| OpenAI | Azure OpenAI| \\n|  --- | ---  |\\n| ```python<br>completion = client.completions.create(<br>    model=\\\"gpt-3.5-turbo-instruct\\\",<br>    prompt=\\\"<prompt>\\\"<br>)<br><br>chat_completion = client.chat.completions.create(<br>    model=\\\"gpt-4o\\\",<br>    messages=\\\"<messages>\\\"<br>)<br><br>embedding = client.embeddings.create(<br>    model=\\\"text-embedding-3-large\\\",<br>    input=\\\"<input>\\\"<br>)<br>``` | ```python<br>completion = client.completions.create(<br>    model=\\\"gpt-35-turbo-instruct\\\", # This must match the custom deployment name you chose for your model.<br>    prompt=\\\"<prompt>\\\"<br>)<br><br>chat_completion = client.chat.completions.create(<br>    model=\\\"gpt-4o\\\", # model = \\\"deployment_name\\\".<br>    messages=\\\"<messages>\\\"<br>)<br><br>embedding = client.embeddings.create(<br>    model=\\\"text-embedding-3-large\\\", # model = \\\"deployment_name\\\".<br>    input=\\\"<input>\\\"<br>)<br>``` |\\n\", \"contentUrl\": \"https://learn.microsoft.com/azure/ai-foundry/openai/how-to/switching-endpoints#keyword-argument-for-model\"}, {\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints (python)\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints (python)\\n## Specify the model\\nOpenAI uses the `model` keyword argument to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/en-us/azure/ai-foundry/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nAzure OpenAI and OpenAI handle model names differently in API calls. OpenAI only needs the model name. Azure OpenAI always needs the deployment name, even when you use the model parameter. You must use the deployment name instead of the model name when you call Azure OpenAI APIs. Our documentation often shows deployment names that match model names to show which model works with each API endpoint. Choose any naming convention for deployment names that works best for you.\\n### **OpenAI**\\n```python\\nresponse = client.responses.create(   \\n    model=\\\"gpt-4.1-nano\\\", \\n    input=\\\"This is a test.\\\"\\n)\\n\\nchat_completion = client.chat.completions.create(\\n    model=\\\"gpt-4o\\\", \\n    messages=\\\"<messages>\\\"\\n)\\n\\nembedding = client.embeddings.create(\\n    model=\\\"text-embedding-3-large\\\", \\n    input=\\\"<input>\\\"\\n)\\n```\\n### **Azure OpenAI**\\n## Azure OpenAI embeddings multiple input support\\nOpenAI and Azure OpenAI currently support input arrays up to 2,048 input items for `text-embedding-ada-002`. Both require the max input token limit per API request to remain under 8,191 for this model.\\n### **OpenAI**\\n```python\\ninputs = [\\\"A\\\", \\\"B\\\", \\\"C\\\"] \\n\\nembedding = client.embeddings.create(\\n    input=inputs,\\n    model=\\\"text-embedding-3-large\\\"\\n)\\n```\\n### **Azure OpenAI**\\n```python\\ninputs = [\\\"A\\\", \\\"B\\\", \\\"C\\\"] #max array size=2048\\n\\nembedding = client.embeddings.create(\\n    input=inputs,\\n    model=\\\"my-text-embedding-3-large-deployment\\\" # This must match the custom deployment name you chose for your model.\\n    # engine=\\\"text-embedding-ada-002\\\"\\n)\\n```\", \"contentUrl\": \"https://learn.microsoft.com/azure/developer/ai/how-to/switching-endpoints#specify-the-model\"}, {\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints (dotnet)\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints (dotnet)\\n## Specify the model\\nOpenAI uses the `model` parameter to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/en-us/azure/ai-foundry/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nAzure OpenAI and OpenAI handle model names differently in API calls. OpenAI only needs the model name. Azure OpenAI always needs the deployment name, even when you use the model parameter. You must use the deployment name instead of the model name when you call Azure OpenAI APIs. Our documentation often shows deployment names that match model names to show which model works with each API endpoint. Choose any naming convention for deployment names that works best for you.\\n### **OpenAI**\\n```csharp\\nstring modelName = \\\"gpt-4.1-nano\\\";\\nOpenAIResponseClient response = client.GetOpenAIResponseClient(modelName);\\n\\nmodelName = \\\"gpt-4o\\\";\\nChatClient chatCompletion = client.GetChatClient(modelName);\\n\\nmodelName = \\\"text-embedding-3-large\\\";\\nEmbeddingClient embedding = client.GetEmbeddingClient(modelName);\\n```\\n### **Azure OpenAI**\\n```csharp\\nstring deploymentName = \\\"my-gpt-4.1-nano-deployment\\\";\\nOpenAIResponseClient response = client.GetOpenAIResponseClient(deploymentName);\\n\\ndeploymentName = \\\"my-gpt-4o-deployment\\\";\\nChatClient chatCompletion = client.GetChatClient(deploymentName);\\n\\ndeploymentName = \\\"my-text-embedding-3-large-deployment\\\";\\nEmbeddingClient embedding = client.GetEmbeddingClient(deploymentName);\\n```\", \"contentUrl\": \"https://learn.microsoft.com/azure/developer/ai/how-to/switching-endpoints#specify-the-model\"}, {\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints (javascript)\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints (javascript)\\n## Specify the model\\nOpenAI uses the `model` keyword argument to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/en-us/azure/ai-foundry/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nAzure OpenAI and OpenAI handle model names differently in API calls. OpenAI only needs the model name. Azure OpenAI always needs the deployment name, even when you use the model parameter. You must use the deployment name instead of the model name when you call Azure OpenAI APIs. Our documentation often shows deployment names that match model names to show which model works with each API endpoint. Choose any naming convention for deployment names that works best for you.\\n### **OpenAI**\\n```javascript\\nconst response = await client.responses.create({\\n  model: \\\"gpt-4.1-nano\\\",\\n  input: \\\"This is a test\\\",\\n});\\n\\nconst chatCompletions = await client.chat.completions.create({\\n  model: \\\"gpt-4o\\\",\\n  messages: [\\\"<messages>\\\"],\\n});\\n\\nconst embeddings = await client.embeddings.create({\\n  model: \\\"text-embedding-3-large\\\",\\n  input: \\\"<input>\\\",\\n});\\n```\\n### **Azure OpenAI**\\n## Azure OpenAI embeddings multiple input support\\nOpenAI and Azure OpenAI currently support input arrays up to 2,048 input items for `text-embedding-ada-002`. Both require the max input token limit per API request to remain under 8,191 for this model.\\n### **OpenAI**\\n```javascript\\nconst embeddings = await client.embeddings.create({\\n    model: \\\"text-embedding-3-large\\\",\\n    inputs: [\\\"A\\\", \\\"B\\\", \\\"C\\\"],\\n})\\n```\\n### **Azure OpenAI**\\n```javascript\\nconst embeddings = await client.embeddings.create({\\n    model: \\\"text-embedding-3-large\\\",\\n    inputs: [\\\"A\\\", \\\"B\\\", \\\"C\\\"],\\n})\\n```\\n# How to switch between OpenAI and Azure OpenAI endpoints (java)\\nThis article shows you how to switch to the new unified OpenAI v1 chat completion endpoint. It covers the common changes and differences when you work with OpenAI and Azure OpenAI.\", \"contentUrl\": \"https://learn.microsoft.com/azure/developer/ai/how-to/switching-endpoints#specify-the-model\"}, {\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints (java)\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints (java)\\n## Specify the model\\nOpenAI uses the `model` keyword argument to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/en-us/azure/ai-foundry/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nAzure OpenAI and OpenAI handle model names differently in API calls. OpenAI only needs the model name. Azure OpenAI always needs the deployment name, even when you use the model parameter. You must use the deployment name instead of the model name when you call Azure OpenAI APIs. Our documentation often shows deployment names that match model names to show which model works with each API endpoint. Choose any naming convention for deployment names that works best for you.\\n### **OpenAI**\\n### **Azure OpenAI**\\n## Azure OpenAI embeddings multiple input support\\nOpenAI and Azure OpenAI currently support input arrays up to 2,048 input items for `text-embedding-ada-002`. Both require the max input token limit per API request to remain under 8,191 for this model.\\n### **OpenAI**\\n```java\\nEmbeddingCreateParams embeddingCreateParams = EmbeddingCreateParams.builder()\\n        .inputOfArrayOfStrings(List.of(\\\"A\\\", \\\"B\\\", \\\"C\\\"))\\n        .model(EmbeddingModel.TEXT_EMBEDDING_3_LARGE)\\n        .build();\\n\\nCreateEmbeddingResponse createEmbeddingResponse = client.embeddings().create(embeddingCreateParams);\\n```\\n### **Azure OpenAI**\\n```java\\nEmbeddingCreateParams embeddingCreateParams = EmbeddingCreateParams.builder()\\n        .inputOfArrayOfStrings(List.of(\\\"A\\\", \\\"B\\\", \\\"C\\\"))\\n        .model(EmbeddingModel.TEXT_EMBEDDING_3_LARGE)\\n        .build();\\n\\nCreateEmbeddingResponse createEmbeddingResponse = client.embeddings().create(embeddingCreateParams);\\n```\\n# How to switch between OpenAI and Azure OpenAI endpoints (golang)\\nThis article shows you how to switch to the new unified OpenAI v1 chat completion endpoint. It covers the common changes and differences when you work with OpenAI and Azure OpenAI.\", \"contentUrl\": \"https://learn.microsoft.com/azure/developer/ai/how-to/switching-endpoints#specify-the-model\"}, {\"title\": \"How to switch between OpenAI and Azure OpenAI endpoints (golang)\", \"content\": \"# How to switch between OpenAI and Azure OpenAI endpoints (golang)\\n## Specify the model\\nOpenAI uses the `Model` keyword argument to specify what model to use. Azure OpenAI has the concept of unique model [deployments](https://learn.microsoft.com/en-us/azure/ai-foundry/openai/how-to/create-resource?pivots=web-portal#deploy-a-model). When you use Azure OpenAI, `Model` should refer to the underlying deployment name you chose when you deployed the model.\\nImportant\\nAzure OpenAI and OpenAI handle model names differently in API calls. OpenAI only needs the model name. Azure OpenAI always needs the deployment name, even when you use the model parameter. You must use the deployment name instead of the model name when you call Azure OpenAI APIs. Our documentation often shows deployment names that match model names to show which model works with each API endpoint. Choose any naming convention for deployment names that works best for you.\\n### **OpenAI**\\n### **Azure OpenAI**\\n## Azure OpenAI embeddings multiple input support\\nOpenAI and Azure OpenAI currently support input arrays up to 2,048 input items for `text-embedding-ada-002`. Both require the max input token limit per API request to remain under 8,191 for this model.\\n### **OpenAI**\\n```go\\nresp, err := client.Embeddings.New(context.TODO(), openai.EmbeddingNewParams{\\n    Model: \\\"text-embedding-3-large\\\",\\n    Input: openai.EmbeddingNewParamsInputUnion{\\n        OfArrayOfStrings: []string{\\\"A\\\", \\\"B\\\", \\\"C\\\"},\\n    },\\n})\\n```\\n### **Azure OpenAI**\\n```go\\nresp, err := client.Embeddings.New(context.TODO(), openai.EmbeddingNewParams{\\n    Model: \\\"text-embedding-3-large\\\",\\n    Input: openai.EmbeddingNewParamsInputUnion{\\n        OfArrayOfStrings: []string{\\\"A\\\", \\\"B\\\", \\\"C\\\"},\\n    },\\n})\\n```\", \"contentUrl\": \"https://learn.microsoft.com/azure/developer/ai/how-to/switching-endpoints#specify-the-model\"}, {\"title\": \"Create and deploy an Azure OpenAI in Azure AI Foundry Models resource (web-portal)\", \"content\": \"# Create and deploy an Azure OpenAI in Azure AI Foundry Models resource (web-portal)\\n## Deploy a model\\nBefore you can generate text or inference, you need to deploy a model. You can select from one of several available models in Azure AI Foundry portal.\\nTo deploy a model, follow these steps:\\n1. Sign in to [Azure AI Foundry portal](https://ai.azure.com/?cid=learnDocs).\\n2. Choose the subscription and the Azure OpenAI resource to work with, and select **Use resource**.\\n3. Under **Management** select **Deployments**.\\n4. Select **Create new deployment** and configure the following fields:\\n | Field | Description |\\n | --- | --- |\\n | **Select a model** | Model availability varies by region. For a list of available models per region, see [Model summary table and region availability](https://learn.microsoft.com/azure/ai-foundry/openai/concepts/models#model-summary-table-and-region-availability). |\\n | **Deployment name** | Choose a name carefully. The deployment name is used in your code to call the model by using the client libraries and the REST APIs. |\\n | **Deployment type** | **Standard**, **Global-Batch**, **Global-Standard**, **Provisioned-Managed**. Learn more about [deployment type options](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/deployment-types). |\\n | **Advanced options** (Optional) | You can set optional advanced settings, as needed for your resource. - For the **Content Filter**, assign a content filter to your deployment. - For the **Tokens per Minute Rate Limit**, adjust the Tokens per Minute (TPM) to set the effective rate limit for your deployment. You can modify this value at any time by using the [**Quotas**](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/quota) menu. [**Dynamic Quota**](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/dynamic-quota) allows you to take advantage of more quota when extra capacity is available. |\\n5. Select a model from the dropdown list.\\n6. Enter a deployment name to identify the model.\\n Important\\n When you access the model via the API, you need to refer to the deployment name rather than the underlying model name in API calls, which is one of the [key differences](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/switching-endpoints) between OpenAI and Azure OpenAI. OpenAI only requires the model name. Azure OpenAI always requires deployment name, even when using the model parameter. In our docs, we often have examples where deployment names are represented as identical to model names to help indicate which model works with a particular API endpoint. Ultimately your deployment names can follow whatever naming convention is best for your use case.\", \"contentUrl\": \"https://learn.microsoft.com/azure/ai-foundry/openai/how-to/create-resource#deploy-a-model\"}, {\"title\": \"Create and deploy an Azure OpenAI in Microsoft Foundry Models resource (classic) (web-portal)\", \"content\": \"# Create and deploy an Azure OpenAI in Microsoft Foundry Models resource (classic) (web-portal)\\n## Deploy a model\\n | **Deployment details** (Optional) | You can set optional advanced settings, as needed for your resource. - For the **Content Filter**, assign a content filter to your deployment. - For the **Tokens per Minute Rate Limit**, adjust the Tokens per Minute (TPM) to set the effective rate limit for your deployment. You can modify this value at any time by using the [**Quotas**](https://learn.microsoft.com/azure/foundry-classic/openai/how-to/quota) menu. [**Dynamic Quota**](https://learn.microsoft.com/azure/foundry-classic/openai/how-to/dynamic-quota) allows you to take advantage of more quota when extra capacity is available. |\\n Important\\n When you access the model via the API, you need to refer to the deployment name rather than the underlying model name in API calls, which is one of the [key differences](https://learn.microsoft.com/azure/foundry-classic/openai/how-to/switching-endpoints) between OpenAI and Azure OpenAI. OpenAI only requires the model name. Azure OpenAI always requires deployment name, even when using the model parameter. In our documentation, we often have examples where deployment names are represented as identical to model names to help indicate which model works with a particular API endpoint. Ultimately your deployment names can follow whatever naming convention is best for your use case.\\n8. Select **Deploy**.\\n9. Deployment **Details** shows all the information of your new deployment. When the deployment completes, your model **Provisioning** state changes to *Succeeded*.\", \"contentUrl\": \"https://learn.microsoft.com/azure/foundry-classic/openai/how-to/create-resource#deploy-a-model\"}, {\"title\": \"Create and deploy an Azure OpenAI in Azure AI Foundry Models resource (ps)\", \"content\": \"# Create and deploy an Azure OpenAI in Azure AI Foundry Models resource (ps)\\n## Deploy a model\\nTo deploy a model, use the [New-AzCognitiveServicesAccountDeployment](https://learn.microsoft.com/en-us/powershell/module/az.cognitiveservices/new-azcognitiveservicesaccountdeployment) command. In the following example, you deploy an instance of the `gpt-4o` model and give it the name *MyModel*. When you try the example, update the code to use your values for the resource group and resource. You don't need to change the `model-version`, `model-format` or `sku-capacity`, and `sku-name` values.\\nThe `Name` property of the `$sku` variable accepts the following deployment types: `Standard`, `GlobalBatch`, `GlobalStandard`, and `ProvisionedManaged`. Learn more about [deployment type options](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/deployment-types).\\nImportant\\nWhen you access the model via the API, you need to refer to the deployment name rather than the underlying model name in API calls, which is one of the [key differences](https://learn.microsoft.com/azure/ai-foundry/openai/how-to/switching-endpoints) between OpenAI and Azure OpenAI. OpenAI only requires the model name. Azure OpenAI always requires deployment name, even when using the model parameter. In our docs, we often have examples where deployment names are represented as identical to model names to help indicate which model works with a particular API endpoint. Ultimately your deployment names can follow whatever naming convention is best for your use case.\\n## Delete a model from your resource\\nYou can delete any model deployed from your resource with the [Remove-AzCognitiveServicesAccountDeployment](https://learn.microsoft.com/en-us/powershell/module/az.cognitiveservices/remove-azcognitiveservicesaccountdeployment) command. In the following example, you delete a model named *MyModel*. When you try the example, update the code to use your values for the resource group, resource, and deployed model.\\n```azurepowershell\\nRemove-AzCognitiveServicesAccountDeployment -ResourceGroupName OAIResourceGroup -AccountName MyOpenAIResource -Name MyModel\\n```\", \"contentUrl\": \"https://learn.microsoft.com/azure/ai-foundry/openai/how-to/create-resource#deploy-a-model\"}]}","server_label":"microsoft-learn"},{"id":"rs_0447f380642eed83006aa11812183887d0a916d1c5c908b8ae","type":"reasoning","content":[],"encrypted_content":"","summary":[]},{"id":"msg_0447f380642eed83006aa1181825e887d09f50e5fc82450935","type":"message","status":"completed","content":[{"type":"output_text","annotations":[],"logprobs":[],"text":"Here are the most relevant Microsoft Learn docs for the OpenAI service (Azure OpenAI):\n\nGet started and overview\n- What is Azure OpenAI in Azure AI Foundry Models: https://learn.microsoft.com/azure/ai-foundry/openai/overview\n- Create and deploy an Azure OpenAI resource (portal/CLI): https://learn.microsoft.com/azure/ai-foundry/openai/how-to/create-resource\n\nBuild apps (quickstarts and how-to)\n- Quickstart: Chat completions (Studio and SDKs): https://learn.microsoft.com/azure/ai-foundry/openai/chatgpt-quickstart\n- Use your own data (RAG) quickstart: https://learn.microsoft.com/azure/ai-foundry/openai/use-your-data-quickstart\n- Assistants API (Preview) overview: https://learn.microsoft.com/azure/ai-foundry/openai/concepts/assistants\n- Switching between OpenAI and Azure OpenAI endpoints: https://learn.microsoft.com/azure/ai-foundry/openai/how-to/switching-endpoints\n\nModels, availability, lifecycle\n- Models and region availability: https://learn.microsoft.com/azure/ai-foundry/openai/concepts/models\n- Model deprecations and retirements: https://learn.microsoft.com/azure/ai-foundry/openai/concepts/model-retirements\n- What’s new in Azure OpenAI: https://learn.microsoft.com/azure/ai-foundry/openai/whats-new\n\nQuotas, limits, monitoring\n- Quotas and limits: https://learn.microsoft.com/azure/ai-foundry/openai/quotas-limits\n- Manage quota (best practices, APIs): https://learn.microsoft.com/azure/ai-foundry/openai/how-to/quota\n- Monitor Azure OpenAI: https://learn.microsoft.com/azure/ai-foundry/openai/how-to/monitor-openai\n\nSafety, privacy, compliance\n- Content filtering (Guardrails) concepts: https://learn.microsoft.com/azure/ai-foundry/openai/concepts/content-filter\n- Abuse monitoring: https://learn.microsoft.com/azure/ai-foundry/openai/concepts/abuse-monitoring\n- Transparency note (responsible AI): https://learn.microsoft.com/azure/ai-foundry/responsible-ai/openai/transparency-note\n\nSDKs and references\n- SDK language support (Python, C#, JS/TS, Java, Go) with Azure OpenAI v1: https://learn.microsoft.com/azure/foundry/openai/supported-languages\n\nIf you want, I can narrow this to a specific task (for example, Python quickstart, Assistants, “on your data,” or quotas) and pull the exact steps and sample code."}],"role":"assistant"}],"parallel_tool_calls":true,"presence_penalty":0.0,"previous_response_id":null,"prompt_cache_key":null,"prompt_cache_retention":"in_memory","reasoning":{"context":"current_turn","effort":"medium","mode":"standard","summary":null},"safety_identifier":null,"service_tier":"default","store":true,"temperature":1.0,"text":{"format":{"type":"text"},"verbosity":"medium"},"tool_choice":"auto","tool_usage":{"image_gen":{"input_tokens":0,"input_tokens_details":{"image_tokens":0,"text_tokens":0},"output_tokens":0,"output_tokens_details":{"image_tokens":0,"text_tokens":0},"total_tokens":0},"web_search":{"num_requests":0}},"tools":[{"type":"mcp","allowed_tools":null,"headers":null,"require_approval":"never","server_description":"A Microsoft Learn MCP server for searching documentation.","server_label":"microsoft-learn","server_url":"https://learn.microsoft.com/api/mcp"}],"top_logprobs":0,"top_p":1.0,"truncation":"disabled","usage":{"input_tokens":50319,"input_tokens_details":{"cache_write_tokens":0,"cached_tokens":0},"output_tokens":3208,"output_tokens_details":{"reasoning_tokens":1920},"total_tokens":53527},"user":null,"metadata":{}},"sequence_number":646}
